namespace Depot.Data;

internal static class FinanceAccountsReceivableSchemaInitializer
{
	public static void Ensure(IDatabaseConnectionFactory connectionFactory)
	{
		using var connection = connectionFactory.CreateConnection();
		connection.Open();
		using var command = connection.CreateCommand();
		foreach (var statement in Statements(connectionFactory.Provider))
		{
			command.CommandText = statement;
			command.Parameters.Clear();
			command.ExecuteNonQuery();
		}
	}

	private static IReadOnlyList<string> Statements(DatabaseProvider provider) => provider switch
	{
		DatabaseProvider.Local => LocalStatements,
		DatabaseProvider.SqlServer => SqlServerStatements,
		DatabaseProvider.MySql => MySqlStatements,
		_ => throw new NotSupportedException($"Finance Accounts Receivable schema initialization is not supported for provider '{provider}'.")
	};

	private static readonly string[] LocalStatements =
	[
		"CREATE TABLE IF NOT EXISTS FinanceReceivablesConfigurations (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, SingletonKey INTEGER NOT NULL DEFAULT 1 UNIQUE, LegalEntityId TEXT NOT NULL, FiscalCalendarId TEXT NOT NULL, InvoicePostingProfileId INTEGER NOT NULL, CreditNotePostingProfileId INTEGER NOT NULL, PaymentPostingProfileId INTEGER NOT NULL, WriteOffPostingProfileId INTEGER NOT NULL, IsActive INTEGER NOT NULL);",
		"CREATE TABLE IF NOT EXISTS FinanceReceivableOpenItems (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, LegalEntityId TEXT NOT NULL, AccountingBookId TEXT NOT NULL, CustomerId INTEGER NOT NULL, Kind INTEGER NOT NULL, SourceType TEXT NOT NULL, SourceId TEXT NOT NULL, SourceReference TEXT NULL, DocumentDate TEXT NOT NULL, DueDate TEXT NOT NULL, CurrencyCode TEXT NOT NULL, OriginalAmount NUMERIC NOT NULL, RemainingAmount NUMERIC NOT NULL, JournalEntryId INTEGER NOT NULL, OperationId TEXT NOT NULL UNIQUE, IsVoided INTEGER NOT NULL DEFAULT 0, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL, UNIQUE(SourceType,SourceId));",
		"CREATE INDEX IF NOT EXISTS IX_FinanceReceivableOpenItems_Customer ON FinanceReceivableOpenItems (CustomerId,CurrencyCode,IsVoided,RemainingAmount,DueDate,Id);",
		"CREATE INDEX IF NOT EXISTS IX_FinanceReceivableOpenItems_Book ON FinanceReceivableOpenItems (AccountingBookId,DocumentDate,Id);",
		"CREATE TABLE IF NOT EXISTS FinanceReceivableAllocations (Id INTEGER PRIMARY KEY AUTOINCREMENT, OperationId TEXT NOT NULL, DebitOpenItemId INTEGER NOT NULL, CreditOpenItemId INTEGER NOT NULL, Amount NUMERIC NOT NULL, AllocationDate TEXT NOT NULL, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL, ReversedAtUtc TEXT NULL, ReversedByUserId INTEGER NULL, ReversalOperationId TEXT NULL);",
		"CREATE INDEX IF NOT EXISTS IX_FinanceReceivableAllocations_Debit ON FinanceReceivableAllocations (DebitOpenItemId,ReversedAtUtc,Id);",
		"CREATE INDEX IF NOT EXISTS IX_FinanceReceivableAllocations_Credit ON FinanceReceivableAllocations (CreditOpenItemId,ReversedAtUtc,Id);",
		"CREATE INDEX IF NOT EXISTS IX_FinanceReceivableAllocations_Operation ON FinanceReceivableAllocations (OperationId,Id);",
		"CREATE TABLE IF NOT EXISTS FinanceReceivableAllocationOperations (OperationId TEXT NOT NULL PRIMARY KEY, RequestHash TEXT NOT NULL, CreditOpenItemId INTEGER NOT NULL, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL);",
		"CREATE TABLE IF NOT EXISTS FinanceReceivablePayments (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, OperationId TEXT NOT NULL UNIQUE, RequestHash TEXT NOT NULL, CustomerId INTEGER NOT NULL, CurrencyCode TEXT NOT NULL, PaymentDate TEXT NOT NULL, Amount NUMERIC NOT NULL, Reference TEXT NULL, Description TEXT NOT NULL, OpenItemId INTEGER NOT NULL, JournalEntryId INTEGER NOT NULL, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL, IsReversed INTEGER NOT NULL DEFAULT 0, ReversalOperationId TEXT NULL UNIQUE, ReversalJournalEntryId INTEGER NULL, ReversedAtUtc TEXT NULL, ReversedByUserId INTEGER NULL);",
		"CREATE INDEX IF NOT EXISTS IX_FinanceReceivablePayments_Customer ON FinanceReceivablePayments (CustomerId,PaymentDate,Id);",
		"CREATE TABLE IF NOT EXISTS FinanceReceivableWriteOffs (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, OperationId TEXT NOT NULL UNIQUE, RequestHash TEXT NOT NULL, OpenItemId INTEGER NOT NULL, Amount NUMERIC NOT NULL, PostingDate TEXT NOT NULL, Reason TEXT NOT NULL, JournalEntryId INTEGER NOT NULL, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL, IsReversed INTEGER NOT NULL DEFAULT 0, ReversalOperationId TEXT NULL UNIQUE, ReversalJournalEntryId INTEGER NULL, ReversedAtUtc TEXT NULL, ReversedByUserId INTEGER NULL);",
		"CREATE INDEX IF NOT EXISTS IX_FinanceReceivableWriteOffs_OpenItem ON FinanceReceivableWriteOffs (OpenItemId,PostingDate,Id);",
		"CREATE TABLE IF NOT EXISTS FinanceDunningPolicies (Id INTEGER PRIMARY KEY AUTOINCREMENT, Version INTEGER NOT NULL DEFAULT 1, LegalEntityId TEXT NOT NULL, Code TEXT NOT NULL, Name TEXT NOT NULL, IsActive INTEGER NOT NULL, UNIQUE(LegalEntityId,Code));",
		"CREATE TABLE IF NOT EXISTS FinanceDunningPolicyLevels (Id INTEGER PRIMARY KEY AUTOINCREMENT, PolicyId INTEGER NOT NULL, LevelNumber INTEGER NOT NULL, MinimumDaysOverdue INTEGER NOT NULL, Code TEXT NOT NULL, Name TEXT NOT NULL, UNIQUE(PolicyId,LevelNumber), UNIQUE(PolicyId,MinimumDaysOverdue));",
		"CREATE TABLE IF NOT EXISTS FinanceDunningRuns (Id INTEGER PRIMARY KEY AUTOINCREMENT, OperationId TEXT NOT NULL UNIQUE, RequestHash TEXT NOT NULL, PolicyId INTEGER NOT NULL, AsOfDate TEXT NOT NULL, CreatedAtUtc TEXT NOT NULL, CreatedByUserId INTEGER NULL);",
		"CREATE TABLE IF NOT EXISTS FinanceDunningRunLines (Id INTEGER PRIMARY KEY AUTOINCREMENT, RunId INTEGER NOT NULL, OpenItemId INTEGER NOT NULL, CustomerId INTEGER NOT NULL, CurrencyCode TEXT NOT NULL, OutstandingAmount NUMERIC NOT NULL, DaysOverdue INTEGER NOT NULL, LevelNumber INTEGER NOT NULL, LevelCode TEXT NOT NULL, UNIQUE(RunId,OpenItemId));",
		"CREATE INDEX IF NOT EXISTS IX_FinanceDunningRunLines_Customer ON FinanceDunningRunLines (RunId,CustomerId,CurrencyCode,OpenItemId);"
	];

